import sys


def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    result = []
    for length in range(1, n + 1):
        count = 0
        for i in range(n - length + 1):
            same = True
            for j in range(length):
                if s[i + j] != s[j]:
                    same = False
                    break
            if same:
                count += 1
        result.append(count)
    print(" ".join(map(str, result)))


main()
